insert into flow.objectives (id, project_id, title, description, status, owner, progress, start_date, target_date, metadata, created_by, deleted_at, created_at, updated_at) values
  ('e0c5270d-0b16-48ed-9083-7e2ad9e48646', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Ship Geiger Notes 1.0 to general availability', 'Take Notes from an internal prototype to a product the whole suite can depend on, released on the 1.0 train with migration tooling and a public changelog.', 'on_track', 'Danielle Reyes', 72, '2026-03-16'::date, '2026-09-27'::date, '{"keyResults":[],"columns":[]}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-03-16T10:15:47.000Z'::timestamptz, '2026-09-12T11:40:51.000Z'::timestamptz),
  ('cf0374b6-8ad0-4903-a2b3-028d33042ada', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Make the editor the best in the suite', 'A block editor that feels instant: sub-16ms keystroke latency, markdown parity, and a slash menu people reach for without thinking.', 'completed', 'Ethan Caldwell', 100, '2026-04-06'::date, '2026-07-12'::date, '{"keyResults":[],"columns":[]}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-04-06T10:15:16.000Z'::timestamptz, '2026-07-12T16:40:22.000Z'::timestamptz),
  ('37cddeef-c064-4e32-ae5b-23d460692252', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Earn enterprise trust', 'Row-level security everywhere, a real audit trail, SSO, and a security posture we can put in front of a procurement team.', 'at_risk', 'Marcus Whitfield', 54, '2026-06-08'::date, '2026-10-11'::date, '{"keyResults":[],"columns":[]}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-06-08T10:15:58.000Z'::timestamptz, '2026-09-12T11:40:31.000Z'::timestamptz),
  ('6290e9ca-ec68-4a2a-aea4-f5ea5874dcca', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Grow activation and weekly retention', 'Get a new workspace to its third saved note inside the first session, and keep half of those workspaces active in week four.', 'on_track', 'Rachel Kim', 41, '2026-07-06'::date, '2026-10-25'::date, '{"keyResults":[],"columns":[]}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-07-06T10:15:11.000Z'::timestamptz, '2026-09-12T11:40:50.000Z'::timestamptz)
