insert into flow.risks (id, project_id, title, description, status, owner, probability, impact, mitigation, review_date, metadata, created_by, deleted_at, created_at, updated_at) values
  ('eafe120d-5ebe-40ce-9cd3-2b8779cee527', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Offline sync conflicts corrupt block order', 'Divergent edits merged out of order can reorder blocks silently, and the user has no way to tell it happened.', 'mitigating', 'Aisha Bennett', 65, 'high', 'Deterministic ordering key per block plus a conflict banner the user has to dismiss.', '2026-09-10'::date, '{"cycle":"c6"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-03T10:00:37.000Z'::timestamptz, '2026-08-23T14:00:17.000Z'::timestamptz),
  ('633832a2-e4b3-42d7-9337-d7748d394484', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'SAML vendor timeline slips past GA', 'The IdP sandbox has been two weeks out for a month. SSO is a procurement blocker for two named accounts.', 'open', 'Marcus Whitfield', 70, 'high', 'Ship GA without SSO behind a documented roadmap date; keep the metadata exchange work merged and flagged.', '2026-09-20'::date, '{"cycle":"c5"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-07-14T10:00:27.000Z'::timestamptz, '2026-08-03T14:00:45.000Z'::timestamptz),
  ('dccf88af-5d76-4ca7-845a-64ad4e89f52a', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Search index rebuild blocks large workspaces', 'A full rebuild takes 40 minutes and holds a lock that makes search return stale results the whole time.', 'mitigating', 'Aisha Bennett', 45, 'medium', 'Incremental reindex with a shadow index and an atomic swap.', '2026-09-07'::date, '{"cycle":"c4"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-06-20T10:00:27.000Z'::timestamptz, '2026-07-10T14:00:57.000Z'::timestamptz),
  ('b3919f93-dba1-4ad6-a1c9-51863839353a', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Service worker pins users to a stale bundle', 'A bad precache manifest can leave a cohort on an old build with no way to self-recover.', 'closed', 'Tyler Brennan', 30, 'high', 'Version-stamped precache paths and a kill switch served from Edge Config.', '2026-08-23'::date, '{"cycle":"c6"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-11T10:00:22.000Z'::timestamptz, '2026-08-31T14:00:42.000Z'::timestamptz),
  ('315fa38b-77a1-4063-92d9-3a507fa82804', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Single maintainer on the editor core', 'Ethan is the only person with the block model in their head. A holiday would stall two cycles.', 'watching', 'Danielle Reyes', 40, 'medium', 'Pair Tyler into the editor work for one day a week and write the data-model doc.', '2026-09-27'::date, '{"cycle":"c3"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-05-15T10:00:30.000Z'::timestamptz, '2026-06-04T14:00:25.000Z'::timestamptz),
  ('2accdcac-7694-4b70-80da-4c3e3015fdd6', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Migration tool writes before the dry-run is trusted', 'An import that partially writes leaves a workspace in a half-migrated state with no clean rollback.', 'mitigating', 'Aisha Bennett', 55, 'high', 'Dry-run produces a diff report; the write path is transactional with a 24-hour undo window.', '2026-09-13'::date, '{"cycle":"c6"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-21T10:00:56.000Z'::timestamptz, '2026-09-10T14:00:50.000Z'::timestamptz),
  ('5abd26ba-8ec9-414e-b987-2d464dfbb570', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Accessibility findings land too late for GA', 'The external audit starts in cycle 7, so anything structural has no room to be fixed.', 'open', 'Grace Donnelly', 50, 'medium', 'Pre-audit self-assessment against the checklist before the reviewer starts.', '2026-09-18'::date, '{"cycle":"c6"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-27T10:00:59.000Z'::timestamptz, '2026-09-12T11:00:33.000Z'::timestamptz),
  ('721e1964-ec6b-49ee-88ff-054e705eef8b', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Realtime costs scale faster than the plan assumes', 'Presence holds a channel per open document; a large workspace opens dozens.', 'watching', 'Marcus Whitfield', 35, 'medium', 'Multiplex presence onto one workspace channel and sample the telemetry.', '2026-10-02'::date, '{"cycle":"c3"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-05-29T10:00:21.000Z'::timestamptz, '2026-06-18T14:00:00.000Z'::timestamptz),
  ('84ff9405-2bee-46dd-a227-4ef84c7acffd', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Battery drain hurts the mobile launch', 'Background sync wakes too often on Android and shows up in device battery settings by name.', 'mitigating', 'Tyler Brennan', 60, 'medium', 'Coalesce sync wakeups behind a 5 minute floor and drop to push-triggered sync.', '2026-09-08'::date, '{"cycle":"c6"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-15T10:00:07.000Z'::timestamptz, '2026-09-04T14:00:17.000Z'::timestamptz)
insert into flow.decisions (id, project_id, title, rationale, status, owner, reversibility, review_date, metadata, created_by, deleted_at, created_at, updated_at) values
  ('0bd38b0b-4d80-49de-a1eb-d2307ccc9e05', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Own the block editor instead of adopting one', 'Every off-the-shelf editor we evaluated forced a document model we would have fought. Owning the block model costs a cycle up front and buys us collaboration and offline later.', 'accepted', 'Ethan Caldwell', 'one_way', '2026-09-08'::date, '{"cycle":"c1"}'::jsonb, 'ab127d9d-9980-4e4b-94ae-02295d8cd74a', null, '2026-04-09T11:30:43.000Z'::timestamptz, '2026-04-23T13:00:11.000Z'::timestamptz),
  ('d428bf0a-ca0b-4a78-bc0e-9162eb73b551', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Give every product its own Postgres schema', 'Notes lives in the notes schema, not public. Shared tables stay in public. Keeps the suite-wide database legible and lets each product own its migration ledger.', 'accepted', 'Aisha Bennett', 'one_way', '2026-08-23'::date, '{"cycle":"c1"}'::jsonb, '8edf3f51-bd5b-43e2-876e-38d37cd37774', null, '2026-03-22T11:30:29.000Z'::timestamptz, '2026-04-05T13:00:59.000Z'::timestamptz),
  ('708e32f0-81fc-45b7-b1b8-a3de8e08a52f', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Autosave rather than an explicit save', 'People lose work to explicit save. Autosave with an optimistic local buffer and a visible sync state is the only option that respects the user.', 'accepted', 'Danielle Reyes', 'reversible', '2026-08-31'::date, '{"cycle":"c2"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-04-19T11:30:09.000Z'::timestamptz, '2026-05-03T13:00:16.000Z'::timestamptz),
  ('695a4f30-cbb7-4cb6-b2b3-b4c28cccd542', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Last-writer-wins for text, ordered merge for structure', 'Full CRDTs were three cycles of work we do not have. Per-block last-writer-wins with a deterministic ordering key covers the cases we actually saw in testing.', 'accepted', 'Aisha Bennett', 'reversible', '2026-09-22'::date, '{"cycle":"c6"}'::jsonb, '8edf3f51-bd5b-43e2-876e-38d37cd37774', null, '2026-08-07T11:30:45.000Z'::timestamptz, '2026-08-21T13:00:09.000Z'::timestamptz),
  ('06a50035-d2e6-45a8-afdc-1be1cb489592', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Ship GA without SAML SSO', 'The IdP timeline is outside our control. Blocking GA on it costs more than shipping with a documented SSO date.', 'proposed', 'Marcus Whitfield', 'reversible', '2026-09-20'::date, '{"cycle":"c7"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-09-02T11:30:34.000Z'::timestamptz, '2026-09-12T11:00:01.000Z'::timestamptz),
  ('6de01e9b-bdac-4b67-97ba-5d2230e26437', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Public share links expire by default', 'Defaulting to no expiry is how link leaks happen. Thirty days by default, never-expire is an explicit choice with a warning.', 'accepted', 'Marcus Whitfield', 'reversible', '2026-09-14'::date, '{"cycle":"c5"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-07-12T11:30:18.000Z'::timestamptz, '2026-07-26T13:00:52.000Z'::timestamptz),
  ('21f0c4da-4b28-4aea-9f42-896d1f2b0eef', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Search runs on Postgres full-text, not a separate engine', 'One fewer system to run and secure. We revisit if p95 search latency goes past 300ms on a real workspace.', 'revisit', 'Aisha Bennett', 'reversible', '2026-09-27'::date, '{"cycle":"c4"}'::jsonb, '8edf3f51-bd5b-43e2-876e-38d37cd37774', null, '2026-06-12T11:30:55.000Z'::timestamptz, '2026-06-26T13:00:28.000Z'::timestamptz),
  ('a4e07974-4e7d-489b-a034-b4e5d325f5fe', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Use the shared geiger/ui kit everywhere', 'No bespoke components unless the kit genuinely lacks one. The suite has to feel like one product.', 'accepted', 'Grace Donnelly', 'reversible', '2026-09-02'::date, '{"cycle":"c1"}'::jsonb, '487b573b-17ab-43b4-84a2-f4625f24d6c3', null, '2026-03-28T11:30:46.000Z'::timestamptz, '2026-04-11T13:00:41.000Z'::timestamptz),
  ('5117a80a-9d57-4425-9bbd-c71ae8034dd8', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Drop the desktop app from the 1.0 scope', 'The PWA covers the offline story. A wrapped desktop build is a distribution problem we do not need on the GA critical path.', 'accepted', 'Danielle Reyes', 'reversible', '2026-09-13'::date, '{"cycle":"c6"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-08-03T11:30:41.000Z'::timestamptz, '2026-08-17T13:00:01.000Z'::timestamptz),
  ('ced0f33d-7fb6-49a8-a160-234ca2a08824', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Store not-yet-promoted config in a metadata jsonb bag', 'Lets a surface grow without a migration per field. Promote to a real column the moment it needs an index or its own policy.', 'accepted', 'Marcus Whitfield', 'reversible', '2026-09-04'::date, '{"cycle":"c1"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-03-24T11:30:19.000Z'::timestamptz, '2026-04-07T13:00:38.000Z'::timestamptz),
  ('33caf714-b908-4ffe-8709-dbb7344dca61', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Encrypt the offline cache with a per-device key', 'An unencrypted IndexedDB copy of a private workspace is a finding waiting to happen on a shared laptop.', 'proposed', 'Aisha Bennett', 'one_way', '2026-09-18'::date, '{"cycle":"c6"}'::jsonb, '8edf3f51-bd5b-43e2-876e-38d37cd37774', null, '2026-08-21T11:30:56.000Z'::timestamptz, '2026-09-04T13:00:22.000Z'::timestamptz)
insert into flow.projections (id, project_id, title, description, kind, starts_on, ends_on, visibility, archived_at, owner, metadata, created_by, deleted_at, created_at, updated_at) values
  ('e00242fe-6eaf-4cba-8969-89264cc90210', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Alpha to the internal suite', 'Notes opens to everyone inside Geiger Studios, feedback via the grounding channels.', 'release', '2026-05-07'::date, '2026-05-10'::date, 'public', null, 'Danielle Reyes', '{"cycle":"c2"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-04-16T10:00:30.000Z'::timestamptz, '2026-05-07T10:00:36.000Z'::timestamptz),
  ('48e86fb4-fb49-4cdd-ad8b-911d58698c29', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Collaboration preview', 'Presence, comments and mentions on for a handful of design partners.', 'release', '2026-06-04'::date, '2026-06-08'::date, 'shared', null, 'Tyler Brennan', '{"cycle":"c3"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-05-14T10:00:36.000Z'::timestamptz, '2026-06-04T10:00:08.000Z'::timestamptz),
  ('a5e66f74-d9bb-4c3b-8f5a-10fe9fecdb62', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Search and structure GA-ready', 'Search, folders and tags considered done pending performance work.', 'milestone', '2026-07-02'::date, '2026-07-05'::date, 'public', null, 'Aisha Bennett', '{"cycle":"c4"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-06-11T10:00:21.000Z'::timestamptz, '2026-07-02T10:00:58.000Z'::timestamptz),
  ('515939d0-6386-4784-8a98-48022dd18e22', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Security review window', 'External penetration test and the remediation pass that follows it.', 'review', '2026-07-20'::date, '2026-07-31'::date, 'shared', null, 'Nathan Okafor', '{"cycle":"c5"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-06-29T10:00:46.000Z'::timestamptz, '2026-07-20T10:00:43.000Z'::timestamptz),
  ('539a6c1e-6f6a-49c3-a3eb-b384616f3f4d', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Sharing and permissions launch', 'Share links, per-note roles and the audit trail go live.', 'release', '2026-08-01'::date, '2026-08-02'::date, 'public', '2026-08-21T12:00:01.000Z'::timestamptz, 'Marcus Whitfield', '{"cycle":"c5"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-07-11T10:00:26.000Z'::timestamptz, '2026-08-01T10:00:51.000Z'::timestamptz),
  ('877c08a9-7b24-4c4e-8eac-9791d350ab5f', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Offline beta', 'Offline sync on for opt-in workspaces behind a flag.', 'milestone', '2026-08-27'::date, '2026-08-30'::date, 'shared', null, 'Aisha Bennett', '{"cycle":"c6"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-08-06T10:00:49.000Z'::timestamptz, '2026-08-27T10:00:26.000Z'::timestamptz),
  ('53a9bf1d-c249-4a35-8726-8284211c8cc5', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Accessibility audit', 'External reviewer walks the whole product against the checklist.', 'review', '2026-09-08'::date, '2026-09-14'::date, 'shared', null, 'Grace Donnelly', '{"cycle":"c7"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-08-18T10:00:18.000Z'::timestamptz, '2026-09-08T10:00:09.000Z'::timestamptz),
  ('2eecd8f2-93ee-48a3-8cce-c7911a02c934', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Release candidate freeze', 'Code freeze, smoke suite and the rollback rehearsal.', 'deadline', '2026-09-20'::date, '2026-09-22'::date, 'public', null, 'Nathan Okafor', '{"cycle":"c7"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-08-30T10:00:58.000Z'::timestamptz, '2026-09-12T10:00:58.000Z'::timestamptz),
  ('fd16bedb-2c4c-44f7-9d5d-eb862224bfb9', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Geiger Notes 1.0', 'General availability across the suite, with the migration tool and public changelog.', 'release', '2026-09-27'::date, '2026-09-28'::date, 'public', null, 'Danielle Reyes', '{"cycle":"c7"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-09-06T10:00:03.000Z'::timestamptz, '2026-09-12T10:00:17.000Z'::timestamptz),
  ('0cbb506b-8f99-4894-bc7e-5fc3195d3059', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'Enterprise readiness review', 'SSO, retention controls and the procurement pack.', 'milestone', '2026-10-04'::date, '2026-10-11'::date, 'shared', null, 'Marcus Whitfield', '{"cycle":"c7"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-09-12T10:00:02.000Z'::timestamptz, '2026-09-12T10:00:42.000Z'::timestamptz)
