insert into flow.grounding_channels (id, project_id, name, description, is_locked, metadata, created_by, deleted_at, created_at, updated_at) values
  ('0e819a87-fc85-4c1c-9181-9da360c4f83e', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'general', 'Everything that does not belong anywhere else.', false, '{}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-03-16T09:00:19.000Z'::timestamptz, '2026-03-16T09:00:16.000Z'::timestamptz),
  ('33745b63-a8c9-483d-9bfb-8a7cf43dd61a', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'engineering', 'Architecture, reviews and the day-to-day build.', false, '{}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-03-16T09:00:06.000Z'::timestamptz, '2026-03-16T09:00:08.000Z'::timestamptz),
  ('b2aa725c-794a-45a7-93e1-8374a0603eae', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'design', 'Design critique, tokens and the component library.', false, '{}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-03-16T09:00:44.000Z'::timestamptz, '2026-03-16T09:00:27.000Z'::timestamptz),
  ('d302a420-8580-4bf3-b5a0-5d606fabc2db', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'releases', 'Deploys, release notes and rollbacks.', false, '{}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-03-16T09:00:52.000Z'::timestamptz, '2026-03-16T09:00:58.000Z'::timestamptz),
