insert into flow.grounding_messages (id, channel_id, body, message_type, is_pinned, metadata, created_by, deleted_at, created_at, updated_at) values
  ('093054f8-4feb-4d4b-aa02-2a6ad07720b1', '0e819a87-fc85-4c1c-9181-9da360c4f83e', 'Kicking off the Notes build today. Cycle 1 is the shell and the schema - nothing user-facing yet.', 'broadcast', true, '{"authorName":"Danielle Reyes"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-03-16T10:00:23.000Z'::timestamptz, '2026-03-16T10:00:58.000Z'::timestamptz),
  ('d57c3cd1-6dc6-43c3-8ec0-eaf55382a991', '0e819a87-fc85-4c1c-9181-9da360c4f83e', 'Repo is up and CI is green on the first commit. Preview deploys land on every PR.', 'message', false, '{"authorName":"Marcus Whitfield"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-03-18T11:03:55.000Z'::timestamptz, '2026-03-18T11:03:43.000Z'::timestamptz),
  ('0d4798d2-1f04-4abd-a6df-30e343aaa685', '0e819a87-fc85-4c1c-9181-9da360c4f83e', 'Dropped the first pass of the editor mockups in the design channel if anyone wants a look.', 'message', false, '{"authorName":"Grace Donnelly"}'::jsonb, '487b573b-17ab-43b4-84a2-f4625f24d6c3', null, '2026-03-22T12:06:42.000Z'::timestamptz, '2026-03-22T12:06:25.000Z'::timestamptz),
  ('49b30500-2a3f-4442-a044-ffe1500e9211', '33745b63-a8c9-483d-9bfb-8a7cf43dd61a', 'Schema is in. Every table is in the notes schema with RLS on from day one, no exceptions.', 'message', true, '{"authorName":"Aisha Bennett"}'::jsonb, '8edf3f51-bd5b-43e2-876e-38d37cd37774', null, '2026-03-21T13:09:21.000Z'::timestamptz, '2026-03-21T13:09:00.000Z'::timestamptz),
  ('851d2e67-55c6-4f48-82bb-f17d4caad8d6', '33745b63-a8c9-483d-9bfb-8a7cf43dd61a', 'The block editor is going to be the hard part. I want to own the data model before anyone builds on top of it.', 'message', false, '{"authorName":"Ethan Caldwell"}'::jsonb, 'ab127d9d-9980-4e4b-94ae-02295d8cd74a', null, '2026-04-09T14:12:03.000Z'::timestamptz, '2026-04-09T14:12:57.000Z'::timestamptz),
  ('ae7eb3f4-5f10-4128-ba5d-4da5cefcc7bb', '33745b63-a8c9-483d-9bfb-8a7cf43dd61a', 'Markdown input rules are in. Typing three dashes gives you a divider now, which is oddly satisfying.', 'message', false, '{"authorName":"Tyler Brennan"}'::jsonb, '6af2bea9-ad17-4fd3-9d65-9c9e961c3f5c', null, '2026-04-23T15:15:22.000Z'::timestamptz, '2026-04-23T15:15:41.000Z'::timestamptz),
  ('2467fc29-4fcb-4c83-acd8-5e9e3643bee6', '33745b63-a8c9-483d-9bfb-8a7cf43dd61a', 'Reminder: no direct DDL. If it is not a migration it does not exist.', 'message', false, '{"authorName":"Marcus Whitfield"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-04-29T16:18:03.000Z'::timestamptz, '2026-04-29T16:18:11.000Z'::timestamptz),
  ('61f90433-a405-4bcb-acbd-dbfdb281fc4e', 'b2aa725c-794a-45a7-93e1-8374a0603eae', 'Token audit done. We had four different greys doing the same job - collapsed them into two.', 'message', true, '{"authorName":"Grace Donnelly"}'::jsonb, '487b573b-17ab-43b4-84a2-f4625f24d6c3', null, '2026-04-02T17:21:40.000Z'::timestamptz, '2026-04-02T17:21:38.000Z'::timestamptz),
  ('270726c1-1867-47d7-92d7-bb221ed7f56f', 'b2aa725c-794a-45a7-93e1-8374a0603eae', 'New share dialog is ready for critique. Third iteration, much less chrome than the last one.', 'message', false, '{"authorName":"Grace Donnelly"}'::jsonb, '487b573b-17ab-43b4-84a2-f4625f24d6c3', null, '2026-07-14T10:24:04.000Z'::timestamptz, '2026-07-14T10:24:49.000Z'::timestamptz),
  ('24b5db7a-e516-4d5a-ab5c-1df52ffd86d7', 'b2aa725c-794a-45a7-93e1-8374a0603eae', 'This reads much better. One ask: make the expiry control feel less optional.', 'message', false, '{"authorName":"Danielle Reyes"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-07-16T11:27:03.000Z'::timestamptz, '2026-07-16T11:27:49.000Z'::timestamptz),
  ('404ae3f3-3bc1-48c2-bc58-11ea2888521c', 'd302a420-8580-4bf3-b5a0-5d606fabc2db', '0.3.0 is out. Editor core, slash menu and autosave. Smoke suite green.', 'message', false, '{"authorName":"Nathan Okafor"}'::jsonb, '7f5c72dc-f10a-464c-9d6f-9977da079cd9', null, '2026-05-09T12:30:19.000Z'::timestamptz, '2026-05-09T12:30:02.000Z'::timestamptz),
  ('a4e0d147-f446-4e31-a425-034d100d29d5', 'd302a420-8580-4bf3-b5a0-5d606fabc2db', '0.5.0 shipped - search, folders and the command palette. Index rebuild is still slow, tracked separately.', 'message', false, '{"authorName":"Nathan Okafor"}'::jsonb, '7f5c72dc-f10a-464c-9d6f-9977da079cd9', null, '2026-07-04T13:33:00.000Z'::timestamptz, '2026-07-04T13:33:38.000Z'::timestamptz),
  ('2a0689b1-e1e8-490f-863d-c204bcad36f5', 'd302a420-8580-4bf3-b5a0-5d606fabc2db', '0.7.0 is live. Share links, per-note roles and the audit trail. This is the one procurement has been waiting for.', 'broadcast', true, '{"authorName":"Marcus Whitfield"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-01T14:36:10.000Z'::timestamptz, '2026-08-01T14:36:38.000Z'::timestamptz),
  ('2581be3c-0753-43ee-840f-210c0a574578', 'd302a420-8580-4bf3-b5a0-5d606fabc2db', '0.8.0-rc1 cut. Offline sync is in but flagged off by default until the conflict work settles.', 'message', false, '{"authorName":"Nathan Okafor"}'::jsonb, '7f5c72dc-f10a-464c-9d6f-9977da079cd9', null, '2026-08-29T15:39:56.000Z'::timestamptz, '2026-08-29T15:39:34.000Z'::timestamptz),
  ('673cbfce-7134-4434-999d-4daae3e39a33', '16b45402-ccd8-460b-b46f-352212ebc7d9', 'Service worker is serving a stale bundle after the 0.8 deploy. Investigating now.', 'broadcast', true, '{"authorName":"Marcus Whitfield"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-13T16:42:57.000Z'::timestamptz, '2026-08-13T16:42:09.000Z'::timestamptz),
  ('21108743-8dca-46f9-ae4f-7358c37f5ccd', '16b45402-ccd8-460b-b46f-352212ebc7d9', 'Confirmed - the precache manifest is not being invalidated. Shipping a version-stamped path.', 'message', false, '{"authorName":"Tyler Brennan"}'::jsonb, '6af2bea9-ad17-4fd3-9d65-9c9e961c3f5c', null, '2026-08-13T17:45:44.000Z'::timestamptz, '2026-08-13T17:45:06.000Z'::timestamptz),
  ('e3a409fb-1362-46dd-8f23-a679fdcb49a9', '16b45402-ccd8-460b-b46f-352212ebc7d9', 'Fix is out, cache busted. Post-mortem goes in the decisions log.', 'message', false, '{"authorName":"Marcus Whitfield"}'::jsonb, 'c318ad4e-a768-419f-9631-78d8880e4821', null, '2026-08-14T10:48:33.000Z'::timestamptz, '2026-08-14T10:48:21.000Z'::timestamptz),
  ('cede7f91-2b14-4659-a2cb-977b8e82412d', '16b45402-ccd8-460b-b46f-352212ebc7d9', 'Expired share links were resolving for up to five minutes after expiry. Patched and backfilled the audit trail.', 'broadcast', true, '{"authorName":"Aisha Bennett"}'::jsonb, '8edf3f51-bd5b-43e2-876e-38d37cd37774', null, '2026-07-25T11:51:53.000Z'::timestamptz, '2026-07-25T11:51:35.000Z'::timestamptz),
  ('039a57a7-0543-40cd-980b-45612b1e0ebf', '0e819a87-fc85-4c1c-9181-9da360c4f83e', 'Activation funnel is instrumented end to end. First cohort numbers land in the retention dashboard next week.', 'message', false, '{"authorName":"Rachel Kim"}'::jsonb, '82a1a7df-b9ba-40f3-9741-0a42b3ea7462', null, '2026-09-04T12:54:39.000Z'::timestamptz, '2026-09-04T12:54:51.000Z'::timestamptz),
  ('a7ac4fb8-a9f1-423f-aece-30f1643047f1', '0e819a87-fc85-4c1c-9181-9da360c4f83e', 'Six cycles done. Cycle 7 is GA hardening - performance, accessibility and the migration tool. Then we ship 1.0.', 'broadcast', true, '{"authorName":"Danielle Reyes"}'::jsonb, '956dfff3-ce70-41a8-9b81-5036e8840cc3', null, '2026-08-31T13:57:36.000Z'::timestamptz, '2026-08-31T13:57:07.000Z'::timestamptz)
insert into flow.planning_boards (id, project_id, nodes, edges, viewport, metadata, created_by, deleted_at, created_at, updated_at) values
  ('66a4563c-c8f6-47ad-92dd-3898026979a2', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', '[{"id":"n-vision","type":"custom","position":{"x":0,"y":0},"data":{"label":"Geiger Notes 1.0 - a suite-native workspace for writing","backgroundColor":"var(--node-default)"},"style":{"width":380,"height":88}},{"id":"n-c1","type":"custom","position":{"x":0,"y":160},"data":{"label":"Cycle 1 - Foundations\nWorkspace shell, Supabase schema, auth and the project switcher - everything the editor needs to sit on."},"style":{"width":360,"height":120}},{"id":"n-c2","type":"custom","position":{"x":420,"y":160},"data":{"label":"Cycle 2 - Editor Core\nThe block editor: slash menu, markdown shortcuts, autosave and the document outline."},"style":{"width":360,"height":120}},{"id":"n-c3","type":"custom","position":{"x":840,"y":160},"data":{"label":"Cycle 3 - Collaboration\nRealtime presence, inline comments, mentions and the notification fan-out."},"style":{"width":360,"height":120}},{"id":"n-c4","type":"custom","position":{"x":0,"y":340},"data":{"label":"Cycle 4 - Search & Structure\nFull-text search, nested folders, tags and the command palette."},"style":{"width":360,"height":120}},{"id":"n-c5","type":"custom","position":{"x":420,"y":340},"data":{"label":"Cycle 5 - Sharing & Permissions\nPublic share links, per-note roles, audit trail and the SSO groundwork."},"style":{"width":360,"height":120}},{"id":"n-c6","type":"custom","position":{"x":840,"y":340},"data":{"label":"Cycle 6 - Offline & Mobile\nOffline-first sync engine, conflict resolution and the installable mobile PWA."},"style":{"width":360,"height":120}},{"id":"n-c7","type":"custom","position":{"x":0,"y":520},"data":{"label":"Cycle 7 - GA Hardening\nPerformance budgets, accessibility pass, migration tooling and the 1.0 release checklist."},"style":{"width":360,"height":120}},{"id":"n-ga","type":"custom","position":{"x":420,"y":700},"data":{"label":"1.0 GA - migration tool, changelog, rollback rehearsal"},"style":{"width":380,"height":92}}