-- Geiger Notes demo dataset (project ebcc7910-1a0e-4e91-8c3b-752f3c4292d3).
--
-- Six months of delivery history (2026-03-16 -> 2026-09-13) across every Flow
-- surface: seven cycles, 87 issues with comments and relations,
-- 44 delivery tasks, objectives/goals, risks, decisions, projections,
-- resourcing, security, assets, vault, grounding channels, a planning board and
-- the activity feed that ties them together.
--
-- Re-runnable: the project's flow.* rows are cleared first, and the shared
-- people rows (auth.users / flow_profiles / organization_users) upsert.
-- Seeds are never ledgered - run with `npm run db:seed`.
--
-- The eight demo teammates are login-disabled: no identities row and no
-- password, so they exist only as assignees, authors and avatars.

-- People ---------------------------------------------------------------

on conflict (id) do update set email = excluded.email, raw_user_meta_data = excluded.raw_user_meta_data;

on conflict (id) do update set organization_id = excluded.organization_id, display_name = excluded.display_name, email = excluded.email, avatar_url = excluded.avatar_url, position = excluded.position, updated_at = excluded.updated_at;

-- Org membership keeps the demo accounts visible to the RLS helpers.
on conflict (id) do nothing;

-- Clean slate for this project only -------------------------------------
delete from flow.issue_comments where issue_id in (select id from flow.issues where project_id = 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3');
